import sys

def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    groups: dict[bytes, int] = {}
    for i in range(1, n + 1):
        key = bytes(sorted(data[i]))
        groups[key] = groups.get(key, 0) + 1
    fact = [1, 1, 2, 6, 24, 120]
    struck = 0
    for key, k in groups.items():
        room = 120
        run = 1
        for j in range(1, 5):
            if key[j] == key[j - 1]:
                run += 1
            else:
                room //= fact[run]
                run = 1
        room //= fact[run]
        if k > room:
            struck += k - room
    print(struck)

main()
